function renderEmbeds(){return pageHeader("Embed Studio","Compose a Discord embed and send it directly to a text channel.")+'<div class="grid">'+card("Build your embed","All fields are optional except the destination channel.",'<div class="form-grid">'+select("channelId","Destination channel",[["","Choose a text channel"],...channels("text")],"")+input("title","Embed title","","text","Announcement title")+input("color","Accent color","#8290ff","color")+input("author","Author","","text","Optional author label")+'<div class="field full"><label for="description">Description</label><textarea id="description" placeholder="Write your embed message…"></textarea></div>'+input("thumbnail","Thumbnail URL","","url","https://…")+input("image","Main image URL","","url","https://…")+input("footer","Footer text","","text","Optional footer")+'</div><div class="actions"><button class="btn primary" id="sendEmbed">Send embed</button></div><div id="feedback"></div>',"full")+'</div>'}
