function renderSupport(){return pageHeader("Starry support","Troubleshoot common dashboard and Discord bot issues.")+'<div class="grid">'+card("Get help","If a dashboard action fails, note the page, action, and exact error message. Do not share bot tokens, passwords, Discord authorization codes, or private credentials.",'<div class="status">For account or server access issues, sign out and retry Discord login. If a feature still fails, keep the exact error message so it can be diagnosed safely.</div>',"full")+"</div>"}
function renderEvents(){return pageHeader("Events & schedule","Create and manage real Discord Scheduled Events for your community.")+'<div class="grid">'+card("Create a scheduled event","Create a voice-channel event or an external event with a location. Starry needs Manage Events permission.",'<div class="form-grid">'+input("eventName","Event name","","text","Community game night")+input("eventStart","Starts at","","datetime-local")+input("eventEnd","Ends at","","datetime-local")+select("eventType","Event type",[["external","External / in-person"],["voice","Discord voice channel"]],"external")+ '<div id="eventLocationWrap">'+input("eventLocation","Location","", "text","e.g. Community stage / online")+'</div><div id="eventChannelWrap" hidden>'+select("eventChannel","Voice channel",[["","Choose a voice channel"],...channels("voice")],"")+'</div><div class="field full"><label for="eventDescription">Description</label><textarea id="eventDescription" maxlength="1000" placeholder="What should attendees expect?"></textarea></div></div><div class="actions"><button class="btn primary" id="createEvent">Create Discord event</button></div><div id="eventFeedback"></div>',"full")+card("Scheduled events","Live events fetched directly from Discord.",'<div id="eventList" class="muted"><div class="empty">Loading scheduled events…</div></div>',"full")+'</div>'}
function renderWelcome(){const w=settings.welcome||{};return pageHeader("Welcome & onboarding","Design the welcome card Starry sends when a new member joins your server.")+'<div class="grid">'+card("Welcome message","Choose a text channel and customize the existing welcome engine. Variables: {user}, {username}, {tag}, {server}, {count}.",'<div class="form-grid">'+select("welcomeChannel","Welcome channel",[["","Choose a text channel"],...channels("text")],w.channelId||"")+input("welcomeTitle","Embed title",w.title||"✨ WELCOME TO {server} ✨")+ '<div class="field full"><label for="welcomeDescription">Welcome description</label><textarea id="welcomeDescription" maxlength="4000">'+esc(w.description||"💖 Hello {user}! We are so overjoyed to have you join our family! 🌟")+'</textarea></div>'+input("welcomePing","Message above the embed",w.pingContent||"💫 Welcome {user}! Grab a seat and enjoy your stay! 🥂")+input("welcomeColor","Embed color",w.color||"#FF73FA","color")+input("welcomeFooter","Embed footer",w.footer||"✨ Enjoy your stellar journey in {server}! ✨")+input("welcomeImage","Banner image / GIF URL",w.image||"","url","https://…")+input("welcomeThumbnail","Thumbnail URL or avatar",w.thumbnail||"avatar","text","avatar or https://…")+'</div><div class="actions"><button class="btn primary" id="saveWelcome">Save welcome settings</button></div><div id="welcomeFeedback"></div><div class="status">Saving here updates the same MongoDB settings used by Starry’s existing guildMemberAdd welcome handler. The selected channel must be a text channel.</div>',"full")+'</div>'}
function renderLeveling(){return pageHeader("Leveling & progression","Manage the live XP system and review member progression stored by Starry.")+'<div class="grid">'+card("Leveling settings","These controls update the existing Starry leveling engine.",check("levelEnabled","Enable leveling","Allow XP and level-up announcements",true)+'<div class="form-grid">'+select("levelLogChannel","Level-up announcement channel",[["","Use the bot default"],...channels("text")],settings.leveling?.logChannelId||"")+input("levelTitle","Announcement title",settings.leveling?.title||"Congratulations {user}!")+input("levelColor","Embed color",settings.leveling?.color||"#5865F2")+ '<div class="field full"><label for="levelDescription">Announcement description</label><textarea id="levelDescription">'+esc(settings.leveling?.description||"Your active participation in **{server}** has paid off! You reached **Level {level}**!")+'</textarea></div></div><div class="actions"><button class="btn primary" id="saveLeveling">Save leveling settings</button></div><div id="levelFeedback"></div>',"full")+card("Live progression","Real XP records from the leveling database.",'<div id="levelStats" class="tiles"><div class="empty">Loading leveling statistics…</div></div><div id="levelLeaderboard" class="muted"></div>',"full")+'</div>'}
function renderEconomy(){return pageHeader("Economy overview","Live member balances and progression from Starry’s existing economy database.")+'<div class="grid">'+card("Server economy","Current totals stored for this server.",'<div id="economyStats" class="tiles"><div class="empty">Loading economy data…</div></div>',"full")+card("Top member balances","The ten highest credit balances in this server.",'<div id="economyLeaderboard" class="muted">Loading leaderboard…</div>',"full")+'</div>'}
async function loadEvents(){const list=$("#eventList");try{const d=await request("/api/guild/"+guildId+"/events");if(!d.events?.length){list.innerHTML='<div class="empty">No scheduled events yet.</div>';return}list.innerHTML=d.events.map(e=>'<div class="check-row"><div><strong>'+esc(e.name)+'</strong><small>'+esc(e.description||"No description")+' · '+(e.entityType===2?"Voice event": "External event")+'</small><small>'+esc(e.start?new Date(e.start).toLocaleString():"Time unavailable")+' → '+esc(e.end?new Date(e.end).toLocaleString():"")+(e.location?" · "+esc(e.location):"")+'</small></div><button class="btn danger" data-cancel-event="'+esc(e.id)+'">Cancel</button></div>').join("");list.querySelectorAll("[data-cancel-event]").forEach(button=>button.addEventListener("click",async()=>{if(!confirm("Cancel this Discord scheduled event?"))return;try{const result=await request("/api/guild/"+guildId+"/events/"+encodeURIComponent(button.dataset.cancelEvent),{method:"DELETE"});$("#eventFeedback").innerHTML=status(result.message,"good");loadEvents()}catch(error){$("#eventFeedback").innerHTML=status(error.message,"bad")}}))}catch(e){list.innerHTML=status(e.message,"bad")}}
async function loadWelcome(){try{const d=await request("/api/guild/"+guildId+"/welcome");settings.welcome=d.settings||{};const w=d.settings||{};const set=(id,value)=>{const el=$("#"+id);if(el)el.value=value??""};set("welcomeChannel",w.channelId||"");set("welcomeTitle",w.title||"");set("welcomeDescription",w.description||"");set("welcomePing",w.pingContent||"");set("welcomeColor",w.color||"#FF73FA");set("welcomeFooter",w.footer||"");set("welcomeImage",w.image||"");set("welcomeThumbnail",w.thumbnail||"avatar")}catch(e){const el=$("#welcomeFeedback");if(el)el.innerHTML=status(e.message,"bad")}}
async function loadLeveling(){try{const d=await request("/api/guild/"+guildId+"/leveling");settings.leveling=d.settings||{};const enabled=$("#levelEnabled");if(enabled)enabled.checked=d.settings?.enabled!==false;const channel=$("#levelLogChannel");if(channel)channel.value=d.settings?.logChannelId||"";const title=$("#levelTitle");if(title)title.value=d.settings?.title||"Congratulations {user}!";const color=$("#levelColor");if(color)color.value=d.settings?.color||"#5865F2";const desc=$("#levelDescription");if(desc)desc.value=d.settings?.description||"";const st=d.stats||{};$("#levelStats").innerHTML=[["Members tracked",st.membersTracked||0],["Total XP",Number(st.totalXp||0).toLocaleString()],["Messages",Number(st.totalMessages||0).toLocaleString()],["Highest level",st.highestLevel||0]].map(([k,v])=>'<div class="tile"><span><small>'+k+'</small><strong>'+v+'</strong></span></div>').join("");$("#levelLeaderboard").innerHTML='<h3>Top XP members</h3>'+(d.leaderboard||[]).map((u,i)=>'<div class="check-row"><strong>#'+(i+1)+' · '+esc(u.userId)+'</strong><span>Level '+Number(u.level||0)+' · '+Number(u.xp||0).toLocaleString()+' XP</span></div>').join("")||'<div class="empty">No XP records yet.</div>'}catch(e){$("#levelStats").innerHTML=status(e.message,"bad")}}
async function loadEconomy(){try{const d=await request("/api/guild/"+guildId+"/economy");const st=d.stats||{};$("#economyStats").innerHTML=[["Members tracked",st.membersTracked||0],["Total credits",Number(st.totalCredits||0).toLocaleString()],["Total XP",Number(st.totalXp||0).toLocaleString()],["Prestige levels",st.totalPrestige||0]].map(([k,v])=>'<div class="tile"><span><small>'+k+'</small><strong>'+v+'</strong></span></div>').join("");$("#economyLeaderboard").innerHTML=(d.leaderboard||[]).map((u,i)=>'<div class="check-row"><strong>#'+(i+1)+' · '+esc(u.userId)+'</strong><span>'+Number(u.credits||0).toLocaleString()+' credits</span></div>').join("")||'<div class="empty">No economy records yet.</div>'}catch(e){$("#economyStats").innerHTML=status(e.message,"bad");$("#economyLeaderboard").textContent=e.message}}

